import type { ChapterId } from "./types";

export interface ChapterMapping {
  id: string;
  title: string;
  grade: "8" | "9" | "10" | "11" | "12";
  subject: "Physics" | "Chemistry" | "Biology" | "Mathematics";
  category: "FOUNDATION" | "JEE_PREP";
  nodeCount: number;
}

export const CHAPTERS_REGISTRY: ChapterMapping[] = [
  // --- LEVEL 1: FOUNDATION TRACK (GRADES 8, 9, 10) ---
  { id: "fnd_08_bio_01", title: "Cell Structure and Functions", grade: "8", subject: "Biology", category: "FOUNDATION", nodeCount: 4 },
  { id: "fnd_09_phy_01", title: "Force and Laws of Motion (CBSE/ICSE)", grade: "9", subject: "Physics", category: "FOUNDATION", nodeCount: 5 },
  { id: "fnd_10_mat_01", title: "Quadratic Equations & Progressions", grade: "10", subject: "Mathematics", category: "FOUNDATION", nodeCount: 6 },

  // --- LEVEL 2: JEE EXAM PREP (GRADES 11, 12) ---
  { id: "p11_01", title: "Units and Measurements", grade: "11", subject: "Physics", category: "JEE_PREP", nodeCount: 7 },
  { id: "p11_02", title: "Motion in a Straight Line", grade: "11", subject: "Physics", category: "JEE_PREP", nodeCount: 8 },
  { id: "p11_03", title: "Laws of Motion", grade: "11", subject: "Physics", category: "JEE_PREP", nodeCount: 8 },
  { id: "p12_01", title: "Electrostatics & Electric Charges", grade: "12", subject: "Physics", category: "JEE_PREP", nodeCount: 2 },
  { id: "p12_02", title: "Current Electricity & Circuits", grade: "12", subject: "Physics", category: "JEE_PREP", nodeCount: 1 },
];

export const CHAPTERS = CHAPTERS_REGISTRY.filter(
  (chapter): chapter is ChapterMapping & { id: ChapterId } =>
    chapter.id === "p11_01" ||
    chapter.id === "p11_02" ||
    chapter.id === "p11_03" ||
    chapter.id === "p12_01" ||
    chapter.id === "p12_02",
);

export function chapterTitle(id: ChapterId): string {
  return CHAPTERS.find((chapter) => chapter.id === id)?.title ?? id;
}
