"use client";

import { CHAPTERS_REGISTRY } from "@/lib/chapters";
import type {
  ExamPrepTrack,
  FoundationTrack,
  GenerateFilters,
  Grade,
  PreparationLevel,
  QuestionType,
  Subject,
} from "@/lib/types";
import { useState } from "react";

interface FilterPanelProps {
  onGenerate: (filters: GenerateFilters) => void;
  loading: boolean;
}

const ALL_TYPES: QuestionType[] = ["MCQ", "NAT", "FITB", "MULTI_CORRECT"];

const FOUNDATION_TRACKS: { value: FoundationTrack; label: string }[] = [
  { value: "CONCEPTUAL_QUIZ", label: "Conceptual Quiz" },
  { value: "CALCULATION_APPLICATION", label: "Calculation Application" },
  { value: "FUTURE_TECH_LAB", label: "Future Tech Applications" },
];

const EXAM_PREP_TRACKS: { value: ExamPrepTrack; label: string }[] = [
  { value: "JEE_MAIN_DRILL", label: "JEE Main Practice Drills" },
  { value: "JEE_ADVANCED_CHALLENGE", label: "JEE Advanced Challenges" },
];

export default function FilterPanel({
  onGenerate,
  loading,
}: FilterPanelProps) {
  const [grade, setGrade] = useState<Grade>("11");
  const [subject, setSubject] = useState<Subject>("Physics");
  const [chapter, setChapter] = useState<GenerateFilters["chapter"]>(
    "p11_01",
  );
  const [difficulty, setDifficulty] =
    useState<GenerateFilters["difficulty"]>("Mixed");
  const [count, setCount] = useState(8);
  const [types, setTypes] = useState<QuestionType[]>([...ALL_TYPES]);
  const [includeAnswerKey, setIncludeAnswerKey] = useState(true);
  const [preparationLevel, setPreparationLevel] =
    useState<PreparationLevel>("JEE_MAIN_ADVANCED");
  const [foundationTracks, setFoundationTracks] = useState<FoundationTrack[]>([
    "CONCEPTUAL_QUIZ",
  ]);
  const [examPrepTracks, setExamPrepTracks] = useState<ExamPrepTrack[]>([
    "JEE_MAIN_DRILL",
  ]);
  const subjectOptions: Subject[] = [
    "Physics",
    ...(["8", "9", "10"].includes(grade) ? ["Biology" as const] : []),
    ...(grade === "10" ? ["Mathematics" as const] : []),
  ];

  function toggleType(t: QuestionType) {
    setTypes((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t],
    );
  }

  function toggleFoundationTrack(t: FoundationTrack) {
    setFoundationTracks((prev) =>
      prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t],
    );
  }

  return (
    <form
      className="no-print space-y-5 rounded-2xl border border-zinc-200 bg-white p-5 shadow-sm lg:sticky lg:top-6"
      onSubmit={(e) => {
        e.preventDefault();
        onGenerate({
          subject,
          grade,
          chapter,
          difficulty,
          types: types.length ? types : ALL_TYPES,
          count,
          includeAnswerKey,
          preparationLevel,
          trackTypes:
            preparationLevel === "FOUNDATION" ? foundationTracks : examPrepTracks,
        });
      }}
    >
      <div>
        <p className="text-xs font-medium uppercase tracking-wide text-zinc-500">
          Class {grade} · {subject} · NCERT
        </p>
        <h2 className="mt-1 text-lg font-semibold text-zinc-900">
          Generate worksheet
        </h2>
      </div>

      <fieldset>
        <legend className="text-sm font-medium text-zinc-700">
          Preparation level
        </legend>
        <div className="mt-2 flex overflow-hidden rounded-lg border border-zinc-300">
          <button
            type="button"
            onClick={() => setPreparationLevel("FOUNDATION")}
            className={`flex-1 px-3 py-2 text-xs font-medium transition ${
              preparationLevel === "FOUNDATION"
                ? "bg-zinc-900 text-white"
                : "bg-white text-zinc-600 hover:bg-zinc-50"
            }`}
          >
            Foundation Track
          </button>
          <button
            type="button"
            onClick={() => setPreparationLevel("JEE_MAIN_ADVANCED")}
            className={`flex-1 border-l border-zinc-300 px-3 py-2 text-xs font-medium transition ${
              preparationLevel === "JEE_MAIN_ADVANCED"
                ? "bg-zinc-900 text-white"
                : "bg-white text-zinc-600 hover:bg-zinc-50"
            }`}
          >
            JEE Exam Prep
          </button>
        </div>
      </fieldset>

      {preparationLevel === "FOUNDATION" ? (
        <fieldset>
          <legend className="text-sm font-medium text-zinc-700">
            Foundation tracks
          </legend>
          <div className="mt-2 flex flex-wrap gap-2">
            {FOUNDATION_TRACKS.map((track) => (
              <label
                key={track.value}
                className={`cursor-pointer rounded-full border px-3 py-1 text-xs font-medium ${
                  foundationTracks.includes(track.value)
                    ? "border-zinc-900 bg-zinc-900 text-white"
                    : "border-zinc-300 text-zinc-600"
                }`}
              >
                <input
                  type="checkbox"
                  className="sr-only"
                  checked={foundationTracks.includes(track.value)}
                  onChange={() => toggleFoundationTrack(track.value)}
                />
                {track.label}
              </label>
            ))}
          </div>
        </fieldset>
      ) : (
        <fieldset>
          <legend className="text-sm font-medium text-zinc-700">
            Exam prep tracks
          </legend>
          <div className="mt-2 flex flex-wrap gap-2">
            {EXAM_PREP_TRACKS.map((track) => (
              <label
                key={track.value}
                className={`cursor-pointer rounded-xl border px-3 py-2 text-xs font-medium ${
                  examPrepTracks[0] === track.value
                    ? "border-zinc-900 bg-zinc-900 text-white"
                    : "border-zinc-300 text-zinc-600"
                }`}
              >
                <input
                  type="radio"
                  className="sr-only"
                  name="exam-prep-track"
                  checked={examPrepTracks[0] === track.value}
                  onChange={() => setExamPrepTracks([track.value])}
                />
                <span className="block">{track.label}</span>
                <span className="mt-1 block text-[11px] font-normal opacity-80">
                  {track.value === "JEE_MAIN_DRILL"
                    ? "Targets: Single-Correct MCQs and standard Integer NAT values"
                    : "Targets: Multi-Correct Selection cards and precise calculation applications"}
                </span>
              </label>
            ))}
          </div>
        </fieldset>
      )}

      <label className="block text-sm font-medium text-zinc-700">
        Grade target
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={grade}
          onChange={(e) => {
            const nextGrade = e.target.value as Grade;
            const nextSubject = ["8", "9", "10"].includes(nextGrade)
              ? subject
              : "Physics";
            setGrade(nextGrade);
            setSubject(nextSubject);
            setPreparationLevel(["8", "9", "10"].includes(nextGrade) ? "FOUNDATION" : "JEE_MAIN_ADVANCED");
            setChapter(
              CHAPTERS_REGISTRY.find(
                (candidate) => candidate.grade === nextGrade && candidate.subject === nextSubject,
              )?.id as GenerateFilters["chapter"] ?? "p11_01",
            );
          }}
        >
          <option value="8">Class 8</option>
          <option value="9">Class 9</option>
          <option value="10">Class 10</option>
          <option value="11">Class 11</option>
          <option value="12">Class 12</option>
        </select>
      </label>

      <label className="block text-sm font-medium text-zinc-700">
        Subject
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={subject}
          onChange={(e) => {
            const nextSubject = e.target.value as Subject;
            setSubject(nextSubject);
            setChapter(
              CHAPTERS_REGISTRY.find(
                (candidate) => candidate.grade === grade && candidate.subject === nextSubject,
              )?.id as GenerateFilters["chapter"] ?? chapter,
            );
          }}
        >
          <option value="Physics">Physics</option>
          {subjectOptions.filter((option) => option !== "Physics").map((option) => (
            <option key={option} value={option}>{option}</option>
          ))}
        </select>
      </label>


      <label className="block text-sm font-medium text-zinc-700">
        Chapter
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={chapter}
          onChange={(e) =>
            setChapter(e.target.value as GenerateFilters["chapter"])
          }
        >
          {CHAPTERS_REGISTRY.filter(
            (c) => c.grade === grade && c.subject === subject,
          ).map((c) => (
            <option key={c.id} value={c.id}>
              {c.title}
            </option>
          ))}
        </select>
      </label>

      <label className="block text-sm font-medium text-zinc-700">
        Difficulty
        <select
          className="mt-1 w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm"
          value={difficulty}
          onChange={(e) =>
            setDifficulty(e.target.value as GenerateFilters["difficulty"])
          }
        >
          <option>Mixed</option>
          <option>Easy</option>
          <option>Medium</option>
          <option>Hard</option>
        </select>
      </label>

      <fieldset>
        <legend className="text-sm font-medium text-zinc-700">
          Question types
        </legend>
        <div className="mt-2 flex flex-wrap gap-2">
          {ALL_TYPES.map((t) => (
            <label
              key={t}
              className={`cursor-pointer rounded-full border px-3 py-1 text-xs font-medium ${
                types.includes(t)
                  ? "border-zinc-900 bg-zinc-900 text-white"
                  : "border-zinc-300 text-zinc-600"
              }`}
            >
              <input
                type="checkbox"
                className="sr-only"
                checked={types.includes(t)}
                onChange={() => toggleType(t)}
              />
              {t === "MCQ"
                ? "Multiple choice"
                : t === "NAT"
                  ? "Numerical"
                  : t === "FITB"
                    ? "Fill in the blank"
                    : "Multi-correct"}
            </label>
          ))}
        </div>
      </fieldset>

      <label className="block text-sm font-medium text-zinc-700">
        Number of questions
        <input
          type="number"
          min={1}
          max={20}
          className="mt-1 w-full rounded-lg border border-zinc-300 px-3 py-2 text-sm"
          value={count}
          onChange={(e) => setCount(Number(e.target.value))}
        />
      </label>

      <label className="flex items-center gap-2 text-sm text-zinc-700">
        <input
          type="checkbox"
          checked={includeAnswerKey}
          onChange={(e) => setIncludeAnswerKey(e.target.checked)}
        />
        Include answer key
      </label>

      <button
        type="submit"
        disabled={loading}
        className="w-full rounded-lg bg-zinc-900 px-4 py-2.5 text-sm font-medium text-white hover:bg-zinc-800 disabled:opacity-60"
      >
        {loading ? "Generating…" : "Generate worksheet"}
      </button>
    </form>
  );
}
